mapper.select:
SELECT 


 ORDER BY ${sortColumn} ${sortDirection}, w.waybill_seq DESC

    LIMIT #{size} OFFSET #{offset}

mapper.insert:
INSERT INTO tb_delivery_event (
    waybill_seq, event_status, reason_code, remark, occurred_at, source, created_by
) VALUES (
    #{waybillSeq}, #{eventStatus}, #{reasonCode}, #{remark},
    COALESCE(#{occurredAt}, CURRENT_TIMESTAMP),
    COALESCE(#{source}, 'MANUAL'), #{createdBy}
)

mapper.select:
SELECT 

 WHERE e.waybill_seq = #{waybillSeq}
 ORDER BY e.occurred_at DESC, e.event_seq DESC

SELECT 

JOIN tb_pack_box b  ON b.box_seq      = w.box_seq
JOIN tb_outbound o  ON o.outbound_seq = b.outbound_seq
JOIN tb_plant    pl ON pl.plant_seq   = o.plant_seq

    AND e.event_status IN ('FAILED','RETURNING','LOST')

        AND ( w.waybill_no  ILIKE '%' || #{keyword} || '%'
           OR o.outbound_no ILIKE '%' || #{keyword} || '%' )


        AND w.courier_code = #{courierCode}


        AND pl.plant_id = #{plantId}


        AND e.occurred_at >= #{fromDate}


        AND e.occurred_at < (#{toDate}::date + 1)




                AND w.issued_by = #{scope.ownerId}


                AND ( pl.org_seq IN

                          #{org}

                      OR w.issued_by = #{scope.ownerId} )




 ORDER BY e.occurred_at DESC, e.event_seq DESC

    LIMIT #{size} OFFSET #{offset}

mapper.insert:
INSERT INTO tb_waybill (
    box_seq, courier_code, waybill_no, waybill_status,
    delivery_status, redelivery_of, issued_by, remark
) VALUES (
    #{boxSeq}, #{courierCode}, #{waybillNo}, 'ISSUED',
    'READY', #{redeliveryOf}, #{issuedBy}, #{remark}
)

sql.where:
AND o.outbound_status = 'SHIPPED' AND w.waybill_status = 'ISSUED' AND w.delivery_status NOT IN ('DELIVERED','LOST')
AND ( k.sku_id ILIKE '%' || #{keyword} || '%' OR pr.product_id ILIKE '%' || #{keyword} || '%' OR pr.product_name ILIKE '%' || #{keyword} || '%' )
AND pl.plant_id = #{plantId}
AND w.courier_code = #{courierCode}
AND b.handed_over_at IS NOT NULL AND b.handed_over_at < CURRENT_TIMESTAMP - (#{delayDaysOrDefault} || ' days')::interval
AND w.issued_by = #{scope.ownerId}
AND ( pl.org_seq IN
#{org}
OR w.issued_by = #{scope.ownerId} )

mapper.select:
SELECT k.sku_id AS sku_id, pr.product_id AS product_id, pr.product_name AS product_name, k.color_code AS color_code, k.size_code AS size_code, SUM(bl.packed_qty)::int AS transit_qty, COUNT(DISTINCT w.waybill_seq)::int AS waybill_count, MAX(CASE WHEN b.handed_over_at IS NULL THEN 0 ELSE DATE_PART('day', CURRENT_TIMESTAMP - b.handed_over_at) END)::int AS oldest_days, COUNT(DISTINCT CASE WHEN b.handed_over_at IS NOT NULL AND b.handed_over_at < CURRENT_TIMESTAMP - (#{delayDaysOrDefault} || ' days')::interval THEN w.waybill_seq END)::int AS delayed_count, COUNT(DISTINCT CASE WHEN w.delivery_status IN ('FAILED','RETURNING') THEN w.waybill_seq END)::int AS stuck_count
GROUP BY k.sku_id, pr.product_id, pr.product_name, k.color_code, k.size_code ORDER BY ${sortColumn} ${sortDirection}, k.sku_id
LIMIT #{size} OFFSET #{offset}
